-- Core objects required by the final blueprint.
create table if not exists inventory.stock_adjustments(id uuid primary key default gen_random_uuid(),product_variant_id uuid not null references catalog.product_variants(id),location_id uuid not null references inventory.locations(id),adjustment_type text not null,quantity numeric(18,3) not null,reason text not null,created_by uuid,created_at timestamptz not null default now());
create table if not exists production.qc_results(id uuid primary key default gen_random_uuid(),inspection_id uuid not null references production.qc_inspections(id) on delete cascade,check_code text not null,result text not null,measured_value numeric,expected_value numeric,unit text,notes text,created_at timestamptz not null default now());
create table if not exists logistics.refunds(id uuid primary key default gen_random_uuid(),order_id uuid not null references commerce.orders(id),return_id uuid references logistics.returns(id),amount numeric(18,2) not null,currency text not null,status text not null default 'pending',reason text,payload jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists ai.conversations(id uuid primary key default gen_random_uuid(),customer_id uuid references customer.customers(id),session_key text unique not null,channel text not null default 'web',status text not null default 'active',context jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists ai.approvals(id uuid primary key default gen_random_uuid(),action_request_id uuid not null references ai.action_requests(id) on delete cascade,decision text not null,decided_by uuid,reason text,created_at timestamptz not null default now());
create table if not exists marketing.experiment_exposures(id uuid primary key default gen_random_uuid(),experiment_id uuid not null references marketing.experiments(id) on delete cascade,variant_id uuid not null references marketing.experiment_variants(id) on delete cascade,subject_key text not null,exposed_at timestamptz not null default now(),context jsonb not null default '{}',unique(experiment_id,subject_key));
alter table inventory.stock_adjustments enable row level security;alter table production.qc_results enable row level security;alter table logistics.refunds enable row level security;alter table ai.conversations enable row level security;alter table ai.approvals enable row level security;alter table marketing.experiment_exposures enable row level security;